const d={render(){const i=document.createElement("div");return i.innerHTML='\n      <div style="max-width:800px;margin:0 auto;padding:40px 24px;font-family:sans-serif;" data-edit-path="div.0">\n        <h2 style="font-size:1.8rem;color:#1A1A1A;margin:0 0 20px;" data-edit-path="div.0/h2.0">Pill Badge: Position, Style &amp; Text</h2>\n        <div style="display:flex;flex-direction:column;gap:14px;margin-bottom:24px;" data-edit-path="div.0/div.0">\n          <div style="padding:18px;background:#fff;border-radius:10px;box-shadow:0 2px 8px rgba(0,0,0,0.07);border-left:3px solid #CC0000;" data-edit-path="div.0/div.0/div.0">\n            <div style="font-weight:700;color:#1A1A1A;margin-bottom:4px;" data-edit-path="div.0/div.0/div.0/div.0">Rule 1 &mdash; Left-aligned at NAME_X, never centered</div>\n            <div style="color:#555;font-size:0.95rem;" data-edit-path="div.0/div.0/div.0/div.1">The pill belongs inside the profile card zone, not floating in the middle of the image.</div>\n          </div>\n          <div style="padding:18px;background:#fff;border-radius:10px;box-shadow:0 2px 8px rgba(0,0,0,0.07);border-left:3px solid #CC0000;" data-edit-path="div.0/div.0/div.1">\n            <div style="font-weight:700;color:#1A1A1A;margin-bottom:4px;" data-edit-path="div.0/div.0/div.1/div.0">Rule 2 &mdash; Title Case only, never ALL CAPS</div>\n            <div style="color:#555;font-size:0.95rem;" data-edit-path="div.0/div.0/div.1/div.1">"AI Tools" &#10003; &nbsp;&nbsp; "AI TOOLS" &#10007; — ALL CAPS was explicitly rejected in testing.</div>\n          </div>\n          <div style="padding:18px;background:#fff;border-radius:10px;box-shadow:0 2px 8px rgba(0,0,0,0.07);border-left:3px solid #CC0000;" data-edit-path="div.0/div.0/div.2">\n            <div style="font-weight:700;color:#1A1A1A;margin-bottom:4px;" data-edit-path="div.0/div.0/div.2/div.0">Rule 3 &mdash; Y position must clear the avatar</div>\n            <div style="color:#555;font-size:0.95rem;" data-edit-path="div.0/div.0/div.2/div.1">pill_y = max(handle_y + handle_height + 14, avatar_bottom + 8) — this guarantees no overlap regardless of text height.</div>\n          </div>\n        </div>\n        <div style="background:#0D0D0D;border-radius:12px;padding:20px 24px;overflow-x:auto;" data-edit-path="div.0/div.1">\n          <div style="color:#888;font-size:0.75rem;margin-bottom:10px;letter-spacing:1px;" data-edit-path="div.0/div.1/div.0">PYTHON SNIPPET</div>\n          <pre style="color:#00D4AA;font-family:monospace;font-size:0.85rem;line-height:1.8;margin:0;" data-edit-path="div.0/div.1/pre.0">pill_y = max(handle_y + handle_h + 14, AV_BOTTOM + 8)\n\ndraw.rounded_rectangle(\n    [NAME_X, pill_y, NAME_X + pill_w, pill_y + pill_h],\n    radius=pill_h // 2, fill=pill_color\n)\ndraw.text(\n    (NAME_X + pill_w // 2, pill_y + pill_h // 2),\n    category.title(),   # .title() enforces Title Case automatically\n    font=pill_font, fill=\'white\', anchor=\'mm\'\n)</pre>\n        </div>\n        <div style="margin-top:16px;padding:14px 18px;background:#fff5f5;border-radius:8px;border-left:3px solid #CC0000;color:#1A1A1A;font-size:0.9rem;" data-edit-path="div.0/div.2">\n          <strong data-edit-path="div.0/div.2/strong.0">&#9888; Most common mistake:</strong> hardcoding a pixel value for pill_y. Always calculate it from the avatar bottom so it adapts to any layout.\n        </div>\n      </div>',i}};export{d as slide};
